--   TORIRS_STDERR_UNBUFFERED=1 ./src/build_<you>_opt/torirsserver --scriptrun \
--       test/raids/construction/workshop.lua --bots 1 --name workshop --ticks 60000 \
--       --session $S/workshop --fixture test/raids/fixtures/fresh_lumbridge.ini

